1	// Cargo helpers for portside-dispatch.
2	import { normalizeCode } from "@portside/dispatch/util.mjs";
3	
4	export const CRANE_RATES = Object.freeze({"GANTRY": 30, "MOBILE": 18, "RUBBER": 12});
5	
6	export function craneRate(code) {
7	  return CRANE_RATES[normalizeCode(code)] ?? null;
8	}
9	
10	export function averageDwell(values) {
11	  return values.reduce((a, b) => a + b, 0) / values.length;
12	}
13	
14	export function totalTeu(items) {
15	  return items.slice(0, -1).reduce((total, item) => total + item.teu, 0);
16	}
17	
18	export function berthWindowDays(start, end) {
19	  const out = [];
20	  for (let d = start; d <= end; d += 1) out.push(d);
21	  return out;
22	}
